// Standalone posting flow. No file upload, OCR provider, network or real menu writes.
(function () {
  'use strict';
  const sampleRows = restaurant => restaurant==='Bếp cô Tư' ? [
    { name:'Cá kho tộ', price:'35000' }, { name:'Đậu hũ sốt nấm', price:'30000' }, { name:'Rau luộc & trứng', price:'30000' }
  ] : [
    { name:'Thịt kho trứng', price:'35000' }, { name:'Gà nướng mật ong', price:'40000' }, { name:'Canh chua cá', price:'35000' }, { name:'Đậu hũ sốt nấm', price:'30000' }
  ];
  const draft = { restaurant:'Cơm nhà An', newRestaurant:'', date:'2026-10-05', deadline:'10:30', mode:'structured', source:'manual', rows:sampleRows('Cơm nhà An'), text:'Thịt kho trứng — 35.000đ\nGà nướng mật ong — 40.000đ\nCanh chua cá — 35.000đ', note:'', sampleImage:false, extracted:false };
  let errors=[], submitted=null;
  const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const money=n=>Number(n||0).toLocaleString('vi-VN')+'đ';
  const restaurantName=()=>draft.restaurant==='new'?draft.newRestaurant.trim():draft.restaurant;
  const notify=t=>{if(typeof window.notify==='function')window.notify(t)};
  const go=p=>{if(typeof window.go==='function')window.go(p)};
  const style=document.createElement('style');style.textContent=`
  .post-root{color:#203529}.post-head{margin-bottom:26px}.post-head h1{margin:8px 0}.post-head p{max-width:710px}.post-eyebrow{font-size:12px;font-weight:750;letter-spacing:1.5px;color:#1f6e45;text-transform:uppercase}.post-grid{display:grid;grid-template-columns:minmax(0,1.5fr) minmax(270px,1fr);gap:22px}.post-stack{display:grid;gap:20px}.post-root .card h2{font-size:21px;margin:0 0 17px}.post-step{display:inline-grid;place-items:center;width:28px;height:28px;border-radius:50%;background:#e7f1e2;color:#1f6e45;font-size:13px;margin-right:9px}.post-field{display:grid;gap:7px;margin:17px 0}.post-field label,.post-field>span{font-size:14px;font-weight:650}.post-field input,.post-field select,.post-field textarea,.post-edit-row input{min-width:0;width:100%;font:inherit;padding:11px 12px;min-height:46px;color:#203529;background:#fff;border:1px solid #bccbb6;border-radius:10px}.post-field textarea{resize:vertical;min-height:100px}.post-row{display:flex;gap:12px;justify-content:space-between;align-items:center;flex-wrap:wrap}.post-two-fields{display:grid;grid-template-columns:1fr 1fr;gap:15px}.post-meta{font-size:13px;color:#63735d}.post-help{font-size:12px;color:#65775d;margin:4px 0}.post-tabs{display:flex;gap:8px;flex-wrap:wrap;margin:14px 0}.post-button{display:inline-flex;align-items:center;justify-content:center;gap:7px;min-height:44px;min-width:44px;font:inherit;font-size:14px;padding:10px 14px;border-radius:11px;border:1px solid #bdcbb6;background:white;color:#203529;cursor:pointer}.post-button.primary{background:#1f6e45;border-color:#1f6e45;color:white}.post-button[aria-pressed=true]{background:#e7f1e2;border-color:#adc6a5;color:#1f6e45}.post-button:disabled{opacity:.55;cursor:default}.post-root input:focus-visible,.post-root textarea:focus-visible,.post-root select:focus-visible,.post-button:focus-visible,.post-summary:focus{outline:3px solid #1f6e45;outline-offset:3px}.post-edit-row{display:grid;grid-template-columns:minmax(0,1fr) 105px 44px;gap:9px;margin:12px 0;align-items:start}.post-edit-label{font-size:12px;color:#5e7256;display:block;margin-bottom:5px}.post-edit-row .post-button{margin-top:23px;padding:9px}.post-error{font-size:13px;color:#96382e;margin:5px 0 0}.post-invalid{border-color:#ae4f40!important}.post-error-summary{padding:18px;border:1px solid #cc998e;background:#fff6f2;border-radius:13px;margin:0 0 22px}.post-error-summary strong{font-size:15px}.post-error-summary ul{margin:8px 0 0;padding-left:20px}.post-error-summary button{padding:4px 0;border:0;min-height:44px;color:#96382e;background:transparent;text-align:left}.post-upload{border:1px dashed #afc0a7;border-radius:15px;background:#f5f8f1;padding:21px;text-align:center;margin:16px 0}.post-upload p{font-size:13px}.post-paper{padding:20px;border-radius:9px;background:#fffdf5;border:1px solid #dfdbcd;text-align:left;margin:16px 0;box-shadow:0 3px 14px #31462c10}.post-paper h3{font-family:Georgia,serif;font-size:21px;margin:0 0 10px}.post-paper ul{padding-left:18px;margin-bottom:0}.post-paper li{font-size:13px;margin:8px 0}.post-summary{position:sticky;top:22px}.post-summary-line{display:flex;justify-content:space-between;gap:16px;border-top:1px solid #e1e8d9;padding:13px 0;font-size:14px}.post-divider{border-top:1px solid #e1e8d9;padding-top:17px;margin-top:18px}.post-wide{width:100%}.post-note{font-size:12px;color:#63735a;border-left:3px solid #adc5a2;padding-left:11px;margin:17px 0}.post-review{max-width:610px;width:calc(100% - 30px);border:1px solid #c7d2c0;border-radius:22px;padding:26px;margin:auto;max-height:calc(100dvh - 32px);overflow:auto;color:#203529}.post-review::backdrop{background:#1c30264f}.post-review h2{font-size:22px;margin:0}.post-review h3{font-size:17px}.post-review-actions{display:flex;justify-content:space-between;gap:10px;flex-wrap:wrap;border-top:1px solid #dce5d5;padding-top:18px;margin-top:22px}.post-success{padding:30px;max-width:720px;margin:auto;text-align:center}.post-success-mark{height:50px;width:50px;margin:0 auto 15px;border-radius:50%;background:#e6f2e2;color:#1f6e45;display:grid;place-items:center}.post-success-mark svg{height:27px;width:27px;fill:none;stroke:currentColor;stroke-width:2;stroke-linecap:round;stroke-linejoin:round}.post-success .post-row{justify-content:center;margin-top:22px}.post-summary-title{font-size:18px;margin:0}.post-fixed-hint{font-size:12px;color:#63735d;margin-top:18px}.post-root [hidden]{display:none!important}
  @media(max-width:640px){.post-grid{grid-template-columns:1fr;gap:19px}.post-summary{position:static}.post-root .card{padding:20px}.post-two-fields{grid-template-columns:1fr;gap:0}.post-edit-row{grid-template-columns:minmax(0,1fr) 84px 44px;gap:7px}.post-edit-row input{font-size:13px;padding:10px 8px}.post-head h1{font-size:27px}.post-review{padding:21px 18px}.post-review-actions .primary{flex:1}.post-tabs .post-button{flex:1;padding:10px 11px}.post-paper{padding:17px}.post-success{padding:26px 20px}.post-success .post-row>.post-button{width:100%}}
  `;document.head.appendChild(style);
  const errorFor=id=>errors.find(e=>e.id===id)?.message||'';
  const errorAttr=id=>errorFor(id)?`aria-invalid="true" aria-describedby="${id}-error" class="post-invalid"`:'';
  const errorMarkup=id=>errorFor(id)?`<p id="${id}-error" class="post-error">${esc(errorFor(id))}</p>`:'';
  function capture(main){
    for(const [key,id] of [['restaurant','post-restaurant'],['newRestaurant','post-new-restaurant'],['date','post-date'],['deadline','post-deadline'],['text','post-text'],['note','post-note']]){const input=main.querySelector('#'+id);if(input)draft[key]=input.value}
    main.querySelectorAll('[data-post-row-name]').forEach(el=>{if(draft.rows[Number(el.dataset.postRowName)])draft.rows[Number(el.dataset.postRowName)].name=el.value});
    main.querySelectorAll('[data-post-row-price]').forEach(el=>{if(draft.rows[Number(el.dataset.postRowPrice)])draft.rows[Number(el.dataset.postRowPrice)].price=el.value});
  }
  function validate(){
    errors=[];if(!restaurantName())errors.push({id:draft.restaurant==='new'?'post-new-restaurant':'post-restaurant',message:'Chọn quán hoặc nhập tên quán mới.'});
    if(!/^\d{4}-\d{2}-\d{2}$/.test(draft.date))errors.push({id:'post-date',message:'Chọn ngày nhận đơn.'});
    if(!/^\d{2}:\d{2}$/.test(draft.deadline))errors.push({id:'post-deadline',message:'Chọn giờ chốt đơn.'});
    if(draft.mode==='plain'){if(!draft.text.trim())errors.push({id:'post-text',message:'Nhập nội dung thực đơn để người đặt biết món.'})}
    else if(!draft.rows.length)errors.push({id:'post-add-row',message:'Thêm ít nhất một món trước khi đăng.'});
    else draft.rows.forEach((r,i)=>{if(!r.name.trim())errors.push({id:'post-name-'+i,message:`Nhập tên món số ${i+1}.`});if(r.price.trim()===''||!Number.isFinite(Number(r.price))||Number(r.price)<0)errors.push({id:'post-price-'+i,message:`Nhập giá hợp lệ cho món số ${i+1}.`})});
    return !errors.length;
  }
  function editorMarkup(){
    if(draft.mode==='plain')return `<div class="post-field"><label for="post-text">Nội dung menu</label><textarea id="post-text" rows="6" ${errorAttr('post-text')}>${esc(draft.text)}</textarea>${errorMarkup('post-text')}<p class="post-help">Người đặt nhập tên món tự do. App không tự tính tiền từ nội dung này.</p></div>`;
    const image=draft.source==='image'?`<div class="post-upload"><strong>Ảnh thực đơn của ${esc(restaurantName()||'quán bạn chọn')}</strong><p>Ảnh mẫu để thử bước đọc món.</p>${draft.sampleImage?`<div class="post-paper"><span class="post-eyebrow">ẢNH MENU MÔ PHỎNG</span><h3>${esc(restaurantName()||'Quán chưa chọn')}</h3><ul>${sampleRows(restaurantName()).map(r=>`<li>${r.name} · ${money(r.price)}</li>`).join('')}</ul></div>`:''}<div class="post-row" style="justify-content:center">${actionButton(draft.sampleImage?'Đổi ảnh mẫu':'Chọn ảnh mẫu','image-pick')}${draft.sampleImage?actionButton(draft.extracted?'Đọc lại danh sách mẫu':'Đọc món từ ảnh mẫu','image-read',true):''}</div></div>`:'';
    return image+`<p class="post-help">${draft.extracted?'Kiểm tra tên món và giá trước khi đăng.':'Tên món và giá bán.'}</p>`+draft.rows.map((r,i)=>`<div class="post-edit-row"><div><label class="post-edit-label" for="post-name-${i}">Món ${i+1}</label><input id="post-name-${i}" data-post-row-name="${i}" value="${esc(r.name)}" ${errorAttr('post-name-'+i)}>${errorMarkup('post-name-'+i)}</div><div><label class="post-edit-label" for="post-price-${i}">Giá (đồng)</label><input id="post-price-${i}" data-post-row-price="${i}" type="number" min="0" step="1000" inputmode="numeric" value="${esc(r.price)}" ${errorAttr('post-price-'+i)}>${errorMarkup('post-price-'+i)}</div>${actionButton('×','delete-row',false,`data-row="${i}" aria-label="Xóa món ${esc(r.name||String(i+1))}"`)}</div>`).join('')+actionButton('+ Thêm món','add-row',false,'id="post-add-row"')+errorMarkup('post-add-row');
  }
  function actionButton(label,action,primary=false,attrs=''){return `<button type="button" class="post-button ${primary?'primary':''}" data-post-action="${action}" ${attrs}>${label}</button>`}
  function pageMarkup(){
    const errorSummary=errors.length?`<section id="post-error-summary" class="post-error-summary" role="alert" tabindex="-1" aria-labelledby="post-errors-title"><strong id="post-errors-title">Kiểm tra ${errors.length} thông tin trước khi xem lại</strong><ul>${errors.map(e=>`<li>${actionButton(esc(e.message),'focus-error',false,`data-target="${e.id}"`)}</li>`).join('')}</ul></section>`:'';
    return `<div class="post-root"><div class="post-head"><span class="post-eyebrow">Dành cho người đăng</span><h1>Đăng menu</h1></div>${errorSummary}<form id="post-form" novalidate><div class="post-grid"><section class="post-stack"><div class="card"><h2><span class="post-step">1</span>Quán & ngày nhận đơn</h2><div class="post-field"><label for="post-restaurant">Menu này của quán nào?</label><select id="post-restaurant" ${errorAttr('post-restaurant')}><option value="">Chọn quán</option>${['Cơm nhà An','Bếp cô Tư'].map(r=>`<option value="${r}" ${draft.restaurant===r?'selected':''}>${r}</option>`).join('')}<option value="new" ${draft.restaurant==='new'?'selected':''}>+ Thêm quán mới</option></select>${errorMarkup('post-restaurant')}<p class="post-help">Đánh giá món được lưu theo quán.</p></div>${draft.restaurant==='new'?`<div class="post-field"><label for="post-new-restaurant">Tên quán mới</label><input id="post-new-restaurant" value="${esc(draft.newRestaurant)}" ${errorAttr('post-new-restaurant')}>${errorMarkup('post-new-restaurant')}</div>`:''}<div class="post-two-fields"><div class="post-field"><label for="post-date">Ngày ăn</label><input id="post-date" type="date" value="${esc(draft.date)}" ${errorAttr('post-date')}>${errorMarkup('post-date')}</div><div class="post-field"><label for="post-deadline">Chốt đơn lúc</label><input id="post-deadline" type="time" value="${esc(draft.deadline)}" ${errorAttr('post-deadline')}>${errorMarkup('post-deadline')}<p class="post-help">Theo giờ Việt Nam</p></div></div></div><div class="card"><h2><span class="post-step">2</span>Nội dung menu</h2><div class="post-tabs" role="group" aria-label="Loại thực đơn">${actionButton('Danh sách món','mode',false,`data-mode="structured" aria-pressed="${draft.mode==='structured'}"`)}${actionButton('Menu viết tay','mode',false,`data-mode="plain" aria-pressed="${draft.mode==='plain'}"`)}</div>${draft.mode==='structured'?`<div class="post-tabs" role="group" aria-label="Cách tạo danh sách">${actionButton('Nhập món','source',false,`data-source="manual" aria-pressed="${draft.source==='manual'}"`)}${actionButton('Từ ảnh menu','source',false,`data-source="image" aria-pressed="${draft.source==='image'}"`)}</div>`:''}${editorMarkup()}<div class="post-field"><label for="post-note">Lưu ý của người đăng · Không bắt buộc</label><textarea id="post-note" placeholder="Ví dụ: chốt sớm hôm nay, nhận cơm tại sảnh…">${esc(draft.note)}</textarea></div></div></section><aside><section class="card post-summary"><h2><span class="post-step">3</span>Trước khi đăng</h2><h3 class="post-summary-title" id="post-summary-restaurant">${esc(restaurantName()||'Chưa chọn quán')}</h3><p class="post-meta" id="post-summary-date">${esc(draft.date)} · Chốt ${esc(draft.deadline)}</p><div class="post-summary-line"><span>Nội dung</span><strong id="post-summary-mode">${draft.mode==='structured'?draft.rows.length+' món':'Menu viết tay'}</strong></div><div class="post-summary-line"><span>Người thu tiền</span><strong>Minh Ngọc</strong></div><p class="post-note">${draft.mode==='structured'?'Người đặt chọn món trong danh sách.':'Người đặt nhập tên món. Không tự tính tiền.'}</p><p class="post-meta">Thông tin chuyển khoản lấy từ Hồ sơ.</p><button type="submit" class="post-button primary post-wide">Xem lại menu</button><p class="post-fixed-hint">Nháp được giữ khi đổi trang.</p></section></aside></div></form></div>`;
  }
  function updateSummary(main){const restaurant=main.querySelector('#post-summary-restaurant');if(restaurant)restaurant.textContent=restaurantName()||'Chưa chọn quán';const date=main.querySelector('#post-summary-date');if(date)date.textContent=draft.date+' · Chốt '+draft.deadline}
  function review(main){
    const dialog=document.createElement('dialog');dialog.className='post-review';dialog.setAttribute('aria-labelledby','post-review-title');dialog.innerHTML=`<div class="post-row"><div><span class="post-eyebrow">Xem lại trước khi đăng</span><h2 id="post-review-title">${esc(restaurantName())}</h2><p class="post-meta">${esc(draft.date)} · Chốt ${esc(draft.deadline)} giờ Việt Nam</p></div>${actionButton('×','cancel',false,'aria-label="Đóng phần xem lại"')}</div><p class="post-note">Quán: ${esc(restaurantName())}.</p>${draft.mode==='structured'?draft.rows.map(r=>`<div class="post-summary-line"><span>${esc(r.name.trim())}</span><strong>${money(r.price)}</strong></div>`).join(''):`<h3>Menu viết tay</h3><p style="white-space:pre-wrap">${esc(draft.text)}</p><p class="post-help">Người đặt nhập tên món tự do; không tự tính tiền.</p>`}${draft.note.trim()?`<div class="post-divider"><h3>Lưu ý</h3><p style="white-space:pre-wrap">${esc(draft.note)}</p></div>`:''}<div class="post-summary-line"><span>Người thu tiền</span><strong>Minh Ngọc</strong></div><div class="post-review-actions">${actionButton('Quay lại chỉnh','cancel')}${actionButton('Đăng menu','publish',true)}</div><p class="post-help">Chỉ tạo trạng thái minh họa trong phiên này.</p>`;document.body.appendChild(dialog);dialog.querySelectorAll('[data-post-action=cancel]').forEach(b=>b.addEventListener('click',()=>dialog.close()));dialog.querySelector('[data-post-action=publish]').addEventListener('click',()=>{submitted={restaurant:restaurantName(),date:draft.date,deadline:draft.deadline,mode:draft.mode,rows:draft.rows.map(r=>({...r})),text:draft.text,note:draft.note};window.previewPublishedMenu={...submitted};window.dispatchEvent(new CustomEvent('preview:menu-posted',{detail:submitted}));dialog.close();draw(main);notify('Đã đăng menu trong bản mẫu — không lưu dữ liệu thật')});dialog.addEventListener('close',()=>dialog.remove(),{once:true});dialog.showModal();
  }
  function successMarkup(){return `<div class="post-root"><section class="card post-success"><div class="post-success-mark"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="m5 12 4 4L19 6"/></svg></div><span class="post-eyebrow">Đã đăng trong bản mẫu</span><h1>Đã đăng menu</h1><p><strong>${esc(submitted.restaurant)}</strong> · ${esc(submitted.date)}<br>Chốt đơn ${esc(submitted.deadline)} · ${submitted.mode==='structured'?submitted.rows.length+' món':'Menu viết tay'}</p><p class="post-meta">Bạn thu tiền cho menu này.</p><div class="post-row">${actionButton('Xem quản lý menu','manage',true)}${actionButton('Đăng menu khác','new')}</div><p class="post-fixed-hint">Menu mẫu, chưa lưu vào ứng dụng.</p></section></div>`}
  function draw(main){
    main.innerHTML=submitted?successMarkup():pageMarkup();
    main.querySelectorAll('[data-post-action]').forEach(el=>el.addEventListener('click',()=>{
      const action=el.dataset.postAction;if(!submitted)capture(main);
      if(action==='mode'){draft.mode=el.dataset.mode;errors=[];draw(main)}
      else if(action==='source'){draft.source=el.dataset.source;errors=[];draw(main)}
      else if(action==='add-row'){draft.rows.push({name:'',price:''});draw(main);main.querySelector('#post-name-'+(draft.rows.length-1)).focus()}
      else if(action==='delete-row'){draft.rows.splice(Number(el.dataset.row),1);errors=[];draw(main)}
      else if(action==='image-pick'){draft.sampleImage=true;draft.extracted=false;draw(main);notify('Đã chọn ảnh thực đơn mẫu của '+(restaurantName()||'quán'))}
      else if(action==='image-read'){draft.rows=sampleRows(restaurantName());draft.extracted=true;errors=[];draw(main);notify('Đã đọc danh sách mô phỏng. Kiểm tra tên và giá trước khi đăng.')}
      else if(action==='focus-error')main.querySelector('#'+el.dataset.target)?.focus();
      else if(action==='manage')go('manage');
      else if(action==='new'){submitted=null;errors=[];draw(main)}
    }));
    const form=main.querySelector('#post-form');if(!form)return;
    form.addEventListener('input',()=>{capture(main);updateSummary(main)});
    main.querySelector('#post-restaurant').addEventListener('change',()=>{capture(main);errors=[];draft.extracted=false;draw(main);if(draft.restaurant==='new')main.querySelector('#post-new-restaurant').focus()});
    form.addEventListener('submit',e=>{e.preventDefault();capture(main);if(!validate()){draw(main);main.querySelector('#post-error-summary').focus();return}review(main)});
  }
  window.renderPostPreview=main=>{draw(main);return true};
})();
